import SwiftUI

struct MovieListView: View {
    @State private var viewModel: MovieListViewModel

    init(viewModel: MovieListViewModel) {
        _viewModel = State(initialValue: viewModel)
    }

    var body: some View {
        content
            .navigationTitle("Popular")
            .task {
                if case .idle = viewModel.state { await viewModel.load() }
            }
    }

    @ViewBuilder
    private var content: some View {
        switch viewModel.state {
        case .idle, .loading:
            ProgressView().frame(maxWidth: .infinity, maxHeight: .infinity)
        case .empty:
            message("No movies found.", systemImage: "film")
        case .failed(let text):
            VStack(spacing: 12) {
                message(text, systemImage: "exclamationmark.triangle")
                Button("Retry") { Task { await viewModel.load() } }
            }
        case .loaded(let movies):
            List {
                ForEach(movies) { movie in
                    MovieRowView(movie: movie)
                        .task { await viewModel.loadNextPageIfNeeded(currentItem: movie) }
                }
                footer
            }
            .listStyle(.plain)
            .refreshable { await viewModel.refresh() }
        }
    }

    @ViewBuilder
    private var footer: some View {
        if viewModel.isLoadingNextPage {
            ProgressView().frame(maxWidth: .infinity)
        } else if let text = viewModel.paginationErrorMessage {
            Text(text).font(.footnote).foregroundStyle(.secondary).frame(maxWidth: .infinity)
        }
    }

    private func message(_ text: String, systemImage: String) -> some View {
        VStack(spacing: 8) {
            Image(systemName: systemImage).font(.largeTitle)
            Text(text).multilineTextAlignment(.center)
        }
        .foregroundStyle(.secondary)
        .padding()
        .frame(maxWidth: .infinity, maxHeight: .infinity)
    }
}
